package mx.com.mesaregia.inventario.api.controller;
import jakarta.validation.Valid; import mx.com.mesaregia.inventario.application.service.*; import mx.com.mesaregia.inventario.api.request.*; import mx.com.mesaregia.inventario.api.response.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/inventario") public class OperacionInventarioController {private final EntradaInventarioService entrada;private final SalidaInventarioService salida;private final RetornoInventarioService retorno;private final AjusteInventarioService ajuste;public OperacionInventarioController(EntradaInventarioService e,SalidaInventarioService s,RetornoInventarioService r,AjusteInventarioService a){entrada=e;salida=s;retorno=r;ajuste=a;}
 @PostMapping("/entradas")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('inventario.gestionar')")public MovimientoResponse entrada(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody EntradaInventarioRequest r){return entrada.registrar(key,r);} 
 @PostMapping("/salidas")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('inventario.gestionar')")public OperacionInventarioResponse salida(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody SalidaInventarioRequest r){return salida.registrar(key,r);} 
 @PostMapping("/retornos")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('inventario.gestionar')")public OperacionInventarioResponse retorno(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody RetornoInventarioRequest r){return retorno.registrar(key,r);} 
 @PostMapping("/ajustes")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('inventario.gestionar')")public MovimientoResponse ajuste(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody AjusteInventarioRequest r){return ajuste.registrar(key,r);} }
